  // Logika spec var representing port state for outgoing data port
  @spec var defenseReadyOut: Base_Types.Boolean = $

  def put_defenseReadyOut(value : Base_Types.Boolean) : Unit = {
    Contract(
      Modifies(defenseReadyOut),
      Ensures(
        defenseReadyOut == value
      )
    )
    Spec {
      defenseReadyOut = value
    }

    Art.putValue(defenseReadyOut_Id, Base_Types.Boolean_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

